import{z as i,x as A,o,c as l,q as d,j as E,D as a,d as s,s as r,S as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"RISC-V 整数指令","description":"","frontmatter":{"title":"RISC-V 整数指令","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/riscv-int-isa.md","filePath":"cs/riscv-int-isa.md","lastUpdated":1791063341000}'),n={name:"cs/riscv-int-isa.md"};function B(C,e,p,F,m,u){const c=A("Mermaid");return o(),l("div",null,[e[2]||(e[2]=d('<h1 id="risc-v-整数指令" tabindex="-1">RISC-V 整数指令 <a class="header-anchor" href="#risc-v-整数指令" aria-label="Permalink to &quot;RISC-V 整数指令&quot;">​</a></h1><div class="epigraph"><p>RV32I 用一套固定格式覆盖运算、访存、分支与跳转；每条指令的语义是对寄存器与内存的确定变换。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；The RISC-V Instruction Set Manual, Volume I 整理</footer></div><p>上一课<a href="/cs/risc-cisc">RISC 与 CISC</a>钉死了字段布局。本课不重拼立即数位，也不从「什么是 RISC」的历史综述另起。缺口是：字段还没有<strong>语义</strong>。数据通路要对着具体指令接线：哪些读寄存器、是否访存、PC 如何更新。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>格式课给出 R/I/S/B/U/J。缺口是 RV32I 核心操作：<code>add</code>/<code>sub</code>/<code>and</code>/<code>or</code>/<code>xor</code>/<code>sll</code>/<code>slt</code> 等 R 型；立即数版本 <code>addi</code>、<code>lw</code> 的地址 <code>rs1+imm</code>、<code>sw</code> 的 S 型；<code>beq</code>/<code>bne</code>/<code>blt</code>/<code>bltu</code> 相对 PC 的偏移；<code>jal</code>/<code>jalr</code> 写返回地址；<code>lui</code>/<code>auipc</code> 建宽常数。<code>x0</code> 硬接 0，写它丢弃。<span class="marginnote">数字实例：硬件里 x0 根本没有存储单元，读它永远得 0，写它等于把结果扔进垃圾桶。伪指令全靠它兜底：<code>mv rd, rs</code> 就是 <code>addi rd, rs, 0</code>，<code>li rd, 100</code> 就是 <code>addi rd, x0, 100</code>。</span></p><p>本课只钉整数用户级子集。CSR、特权、浮点、<code>fence</code> 的完整内存模型后置。</p><h3 id="addi-不是「把立即数当无符号」" tabindex="-1"><code>addi</code> 不是「把立即数当无符号」 <a class="header-anchor" href="#addi-不是「把立即数当无符号」" aria-label="Permalink to &quot;`addi` 不是「把立即数当无符号」&quot;">​</a></h3><p>12 位立即数符号扩展再加，与<a href="/cs/twos-complement">补码</a>一致。<code>sltiu</code> 把扩展后的值当无符号比。把所有 <code>*i</code> 当零扩展，负数立即数会错。移位量只取低 5 位（RV32）。</p><p><span class="marginnote">Patterson/Hennessy 第 2 章用 RV32I 当全书例子。官方手册是规范；本课按教材范围：够画单周期数据通路的那些指令。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每类指令列：用哪些寄存器口、ALU 作什么、是否读/写内存、下一 PC 是 +4 还是 PC+offset 或 jalr 目标。分支比较用<a href="/cs/comparator-circuit">比较器</a>或 ALU 零/小于。加载宽度 <code>lw</code>/<code>lh</code>/<code>lb</code> 与符号扩展、零扩展要分开。</p>',11)),(o(),E(t,null,{default:a(()=>[r(c,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FMT%5B%22RISC-V%20%E6%A0%BC%E5%BC%8F%22%5D%20--%3E%20OP%5B%22%E8%BF%90%E7%AE%97%20%2F%20%E8%AE%BF%E5%AD%98%20%2F%20%E5%88%86%E6%94%AF%22%5D%0A%20%20OP%20--%3E%20SEM%5B%22%E5%AF%B9%E5%AF%84%E5%AD%98%E5%99%A8%E4%B8%8E%E5%86%85%E5%AD%98%E7%9A%84%E5%8F%98%E6%8D%A2%22%5D%0A%20%20SEM%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%E7%AB%AF%E5%8F%A3%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了语义，才能说「这条指令需要两个读口、一个写口、ALU、数据存储器」。没有的功能（整数除法在 M 扩展）本课不假装存在。伪指令 <code>li</code>、<code>mv</code> 是汇编器合成，硬件仍只看见真实编码。</p><p><span class="marginnote">常见误区：以为 <code>sw</code> 要「先读内存再写」。它只读寄存器（基址与待存数据）、只写内存，不碰内存读口——数据通路上存储器的读与写端口是分开的，这也是 <code>sw</code> 不产生 rd 写回的原因。</span></p><p>12 位立即数只够表示 \\(\\pm 2048\\)，要装大常数就先 <code>lui</code> 装高 20 位、再 <code>addi</code> 补低 12 位——像先写上门牌的大区号，再补门牌尾号。<span class="marginnote"><code>auipc</code> 同理，只是基准换成当前 PC：<code>auipc rd, 0</code> 直接把 PC 存进寄存器，是位置无关代码取「自己地址」的标准手法。</span></p>',4)),(o(),E(t,null,{default:a(()=>[r(c,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLS%5B%22%E4%B8%80%E6%9D%A1%20RV32I%20%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20R%5B%22R%20%E5%9E%8B%E8%BF%90%E7%AE%97%EF%BC%9A%E8%AF%BB%202%20%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%8CALU%EF%BC%8C%E5%86%99%201%20%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%8Cpc%2B4%22%5D%0A%20%20CLS%20--%3E%20L%5B%22lw%EF%BC%9A%E8%AF%BB%201%20%E5%AF%84%E5%AD%98%E5%99%A8%E5%8A%A0%E7%AB%8B%E5%8D%B3%E6%95%B0%E7%AE%97%E5%9C%B0%E5%9D%80%EF%BC%8C%E8%AE%BF%E5%AD%98%EF%BC%8C%E5%86%99%201%20%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%8Cpc%2B4%22%5D%0A%20%20CLS%20--%3E%20S%5B%22sw%EF%BC%9A%E8%AF%BB%202%20%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%8C%E5%8F%AA%E5%86%99%E5%86%85%E5%AD%98%EF%BC%8Cpc%2B4%22%5D%0A%20%20CLS%20--%3E%20B%5B%22beq%EF%BC%9A%E8%AF%BB%202%20%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%8C%E6%AF%94%E8%BE%83%E5%99%A8%E5%AE%9A%E5%88%86%E6%94%AF%EF%BC%8Cpc%2B%E5%81%8F%E7%A7%BB%22%5D%0A%20%20CLS%20--%3E%20J%5B%22jal%EF%BC%9A%E4%B8%8D%E8%AF%BB%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%8C%E5%86%99%20ra%EF%BC%8Cpc%20%E8%B7%B3%E7%9B%AE%E6%A0%87%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p>对齐：<code>lw</code> 地址应 4 的倍数，否则异常——入口课再接。本课承认约束。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲向量、不把 Linux syscall 编号当 ISA。RV64 只把寄存器与立即数加宽，本课以 32 位教学。压缩指令是同一语义的另一编码。</p><p>后课默认：谈到「一条整数指令」，语义在 RV32I 这张表上；硬件要提供 32×32 位寄存器与按语义接线的功能单元。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RV32I 给出运算、访存、分支、跳转的确定语义。</li><li><code>x0</code> 为 0；立即数多数符号扩展。</li><li>伪指令不是额外硬件。寄存器堆下一课实现。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V ISA Manual, Vol. I。</li></ul>',6))])}const S=i(n,[["render",B]]);export{_ as __pageData,S as default};
